/**
 * The shape of the component catalog: one entry per component, hook or utility.
 *
 * The catalog is the single source for the written docs (`docs/components/*.md`, generated by `npm run docs`) and for
 * the API reference on the demo's /components page. It is plain data with no React, so Node can read it directly.
 * `npm run docs:check` fails when an exported component is missing here or a documented prop no longer exists.
 */

export type GroupId = 'ui' | 'forms' | 'nav' | 'overlays' | 'data' | 'charts' | 'calendar' | 'media' | 'theme' | 'foundation'

export interface GroupDoc {
  id: GroupId
  title: string
  description: string
}

export interface PropDoc {
  name: string
  /** The TypeScript type as a reader should see it, e.g. `'primary' | 'ghost'`. */
  type: string
  description: string
  default?: string
  /** True for props without which the component does not work. */
  required?: boolean
}

export interface ComponentDoc {
  /** Lowercase, unique, used for anchors. */
  id: string
  /** The name people import. */
  name: string
  group: GroupId
  kind?: 'component' | 'hook' | 'type' | 'utility'
  /** One sentence: what it is for. */
  summary: string
  /** File under `src/`, e.g. `kit/components/ui/Button.tsx`. Checked to exist. */
  source: string
  /** Every exported name this entry covers (defaults to `[name]`). Used to check coverage. */
  exports?: string[]
  /** Names shown in the import line. Defaults to `exports`, or `[name]`. Use `[]` to show no import line. */
  imports?: string[]
  /** Props, or parameters for hooks and functions. Each name is checked to appear in `source`. */
  props?: PropDoc[]
  /** A short, working usage snippet. */
  example: string
  /** Behavior worth knowing: keyboard, accessibility, edge cases. */
  notes?: string[]
}

/** Shorthand for a prop row. */
export const prop = (
  name: string,
  type: string,
  description: string,
  options: { default?: string; required?: boolean } = {},
): PropDoc => ({ name, type, description, ...options })

/** The import statement for an entry, or an empty string when it has none (e.g. a group of utilities). */
export function importStatement(doc: ComponentDoc): string {
  const names = doc.imports ?? doc.exports ?? [doc.name]
  if (!names.length) return ''
  const from = `@/${doc.source.replace(/\.(tsx?|ts)$/, '')}`
  return `import ${doc.kind === 'type' ? 'type ' : ''}{ ${names.join(', ')} } from '${from}'`
}
